using Idb.Libraries.Abstractions.Enums;
using Idb.Libraries.Abstractions.Options;

namespace Idb.Libraries.Abstractions.Dtos;

/// <summary>
/// Defines per-contract settings used to locate InterfaceDB assets generated by the migration tool.
/// </summary>
public interface IDbContractConfigDto<TContract>
    where TContract : class, IStoredContract<TContract>
{
    /// <summary>
    /// Unique key used to register contract-specific services (e.g., keyed DI lookups).
    /// </summary>
    string EnvelopeDICacheKey { get; }

    /// <summary>
    /// Logical contract name used to resolve scoped interfaces and storage roots.
    /// </summary>
    string ContractName { get; }
    /// <summary>
    /// Default file extension produced by this serializer (e.g., ".mpk").
    /// </summary>
    string FileExtension { get; }

    /// <summary>
    /// Absolute or project-relative path to the folder containing contract implementations (maps to the tool's storage/implementations option).
    /// </summary>
    string? ImplementationsPath { get; }

    /// <summary>
    /// Absolute or project-relative path to the folder containing the contract interface versions.
    /// </summary>
    string? ContractPath { get; }

    /// <summary>
    /// Path to the migrations directory produced by the tooling for this contract.
    /// </summary>
    string? MigrationsPath { get; }

    /// <summary>
    /// Optional data root directory where persisted artifacts are stored.
    /// </summary>
    string? DataRoot { get; }

    /// <summary>
    /// Version tag representing the currently active contract baseline (e.g., "1.0.1").
    /// </summary>
    string? ActiveVersion { get; }

    /// <summary>
    /// Repository implementation used to service this contract.
    /// </summary>
    ContractRepositoryType RepositoryType { get; }

    /// <summary>
    /// Controls whether the factory-resolved identity represents one stored object or many physical objects.
    /// </summary>
    StorageObjectCardinality ObjectCardinality => StorageObjectCardinality.Multiple;

    /// <summary>
    /// Optional storage policy that tweaks repository behavior (buffer sizes, concurrency, notifications).
    /// </summary>
    StoragePolicy? StoragePolicy { get; }
}
